// Student-t quantiles via regularized incomplete beta (no normal approximation).
function logGamma(z){const c=[676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-.13857109526572012,9.984369578019572e-6,1.5056327351493116e-7];if(z<.5)return Math.log(Math.PI)-Math.log(Math.sin(Math.PI*z))-logGamma(1-z);z--;let x=.99999999999980993;for(let i=0;i<c.length;i++)x+=c[i]/(z+i+1);const t=z+c.length-.5;return .5*Math.log(2*Math.PI)+(z+.5)*Math.log(t)-t+Math.log(x);}
function fraction(a,b,x){const tiny=1e-300;let c=1,d=1-(a+b)*x/(a+1);if(Math.abs(d)<tiny)d=tiny;d=1/d;let h=d;for(let m=1;m<=300;m++){let aa=m*(b-m)*x/((a+2*m-1)*(a+2*m));d=1+aa*d;if(Math.abs(d)<tiny)d=tiny;c=1+aa/c;if(Math.abs(c)<tiny)c=tiny;d=1/d;h*=d*c;aa=-(a+m)*(a+b+m)*x/((a+2*m)*(a+2*m+1));d=1+aa*d;if(Math.abs(d)<tiny)d=tiny;c=1+aa/c;if(Math.abs(c)<tiny)c=tiny;d=1/d;const delta=d*c;h*=delta;if(Math.abs(delta-1)<3e-14)break;}return h;}
function beta(x,a,b){if(x<=0)return 0;if(x>=1)return 1;const front=Math.exp(logGamma(a+b)-logGamma(a)-logGamma(b)+a*Math.log(x)+b*Math.log1p(-x));return x<(a+1)/(a+b+2)?front*fraction(a,b,x)/a:1-front*fraction(b,a,1-x)/b;}
export function tCritical(level,df){if(!(level>0&&level<1&&df>0))throw Error('Invalid confidence level/degrees of freedom.');const tail=(1-level)/2;const upper=x=>.5*beta(df/(df+x*x),df/2,.5);let lo=0,hi=1;while(upper(hi)>tail)hi*=2;for(let i=0;i<80;i++){const mid=(lo+hi)/2;if(upper(mid)>tail)lo=mid;else hi=mid;}return(lo+hi)/2;}
export function describe(values,level=.95){const valid=values.filter(Number.isFinite),n=valid.length;const mean=n?valid.reduce((a,b)=>a+b,0)/n:null;const variance=n>1?valid.reduce((a,b)=>a+(b-mean)**2,0)/(n-1):null;const std=variance===null?null:Math.sqrt(variance),halfWidth=n>1?tCritical(level,n-1)*std/Math.sqrt(n):null;return{n,total:values.length,missing:values.length-n,mean,std,min:n?Math.min(...valid):null,max:n?Math.max(...valid):null,ci95:n>1?tCritical(.95,n-1)*std/Math.sqrt(n):null,confidence:{level,halfWidth,lower:halfWidth===null?null:mean-halfWidth,upper:halfWidth===null?null:mean+halfWidth}};}
export function difference(a,b,level=.95){if(!a||!b||a.n<2||b.n<2)return{mean:a?.mean!=null&&b?.mean!=null?b.mean-a.mean:null,lower:null,upper:null,method:'Welch independent approximation; insufficient samples'};const va=a.std*a.std/a.n,vb=b.std*b.std/b.n,se=Math.sqrt(va+vb),df=se?((va+vb)**2/(va*va/(a.n-1)+vb*vb/(b.n-1))):Math.min(a.n,b.n)-1;const mean=b.mean-a.mean,half=tCritical(level,df)*se;return{mean,lower:mean-half,upper:mean+half,method:'Welch independent approximation'};}
